// Zero-Hallucination Quality Gate
const fs = require('fs');
const registryPath = '/opt/etf-collector/etf_fee_registry.json';

if (!fs.existsSync(registryPath)) {
  throw new Error('Fee registry file does not exist after execution.');
}

const content = fs.readFileSync(registryPath, 'utf8');
const items = JSON.parse(content);

const complete3Tier = items.filter(d => 
  d.total_fee_pct != null && 
  (d.other_cost_pct != null || d.ter_pct != null) && 
  d.trading_cost_pct != null
).length;

const coveragePct = (complete3Tier / items.length) * 100;

if (items.length < 900) {
  throw new Error(`Critical: Universe size too small (${items.length}). Scraper degraded.`);
}

return [
  {
    json: {
      status: 'SUCCESS',
      totalEtfs: items.length,
      complete3Tier: complete3Tier,
      coveragePct: coveragePct.toFixed(1) + '%',
      fileContentBase64: Buffer.from(content).toString('base64'),
      timestamp: new Date().toISOString()
    }
  }
];
